<?php
require 'db.php'; session_start(); require 'includes.php';
if (($_SESSION['user_role'] ?? '') !== 'admin') { header('Location: login.php'); exit; }

function rooms_redirect(): void { header('Location: admin_rooms.php'); exit; }
function save_room_images(mysqli $conn, int $roomId): void {
    $delete = array_values(array_filter(array_map('intval', $_POST['delete_image'] ?? [])));
    $coverRemoved = false;
    if ($delete) {
        $placeholders = implode(',', array_fill(0, count($delete), '?'));
        $types = 'i' . str_repeat('i', count($delete));
        $values = array_merge([$roomId], $delete);
        $cover = $conn->query("SELECT id FROM room_images WHERE room_id=$roomId ORDER BY sort_order,id LIMIT 1")->fetch_assoc();
        $coverRemoved = $cover && in_array((int)$cover['id'], $delete, true);
        $q = $conn->prepare("SELECT id,image_path FROM room_images WHERE room_id=? AND id IN ($placeholders)");
        $q->bind_param($types, ...$values); $q->execute(); $files=$q->get_result();
        while($f=$files->fetch_assoc()){ $absolute=__DIR__.'/'.$f['image_path']; if(is_file($absolute)) unlink($absolute); }
        $q=$conn->prepare("DELETE FROM room_images WHERE room_id=? AND id IN ($placeholders)"); $q->bind_param($types, ...$values); $q->execute();
    }
    $uploads=$_FILES['room_images']??$_FILES['images']??null;
    $selected=$uploads ? count(array_filter($uploads['name']??[])) : 0;
    $count=(int)$conn->query("SELECT COUNT(*) c FROM room_images WHERE room_id=$roomId")->fetch_assoc()['c'];
    if ($count + $selected > 3) throw new Exception('A room can have a maximum of 3 images.');

    if ($coverRemoved && $selected) {
        $q=$conn->prepare('UPDATE room_images SET sort_order=sort_order+? WHERE room_id=?'); $q->bind_param('ii',$selected,$roomId); $q->execute();
        $count = 0;
    } else {
        $images=$conn->query("SELECT id FROM room_images WHERE room_id=$roomId ORDER BY sort_order,id"); $order=0;
        while($image=$images->fetch_assoc()){ $order++; $q=$conn->prepare('UPDATE room_images SET sort_order=? WHERE id=?'); $q->bind_param('ii',$order,$image['id']); $q->execute(); }
        $count=$order;
    }
    if (!$uploads || !$selected) return;
    $directory=__DIR__.'/uploads/rooms'; if(!is_dir($directory) && !mkdir($directory,0755,true) && !is_dir($directory)) throw new Exception('Could not create the room image directory.');
    foreach($uploads['name'] as $index=>$name){ if($name==='') continue; if($uploads['error'][$index]!==UPLOAD_ERR_OK) throw new Exception('One of the room images could not be uploaded.'); if($uploads['size'][$index]>5*1024*1024) throw new Exception('Each room image must be smaller than 5 MB.'); $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp'],true)) throw new Exception('Use only JPG, JPEG, PNG, or WEBP room images.'); $path='uploads/rooms/room_'.$roomId.'_'.bin2hex(random_bytes(8)).'.'.$ext; if(!move_uploaded_file($uploads['tmp_name'][$index],__DIR__.'/'.$path)) throw new Exception('Could not save a room image.'); $order=++$count; $q=$conn->prepare('INSERT INTO room_images (room_id,image_path,sort_order) VALUES (?,?,?)');$q->bind_param('isi',$roomId,$path,$order);$q->execute(); }
}

if ($_SERVER['REQUEST_METHOD']==='POST') {
  $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
  if($action==='delete'){ $q=$conn->prepare('DELETE FROM rooms WHERE id=?');$q->bind_param('i',$id);$q->execute();flash($q->affected_rows?'success':'error',$q->affected_rows?'Room deleted.':'Room not found.');rooms_redirect(); }
  $number=trim($_POST['room_number']??'');$type=trim($_POST['room_type']??'');$block=trim($_POST['hostel_block']??'');$floor=trim($_POST['floor']??'');$location=trim($_POST['location']??'');$beds=(int)($_POST['total_beds']??0);$fees=(float)($_POST['fees_per_sem']??-1);$status=$_POST['room_status']??'Available';
  if(!$number||!$type||!$block||!$floor||$beds<1||$fees<0||!in_array($status,['Available','Maintenance'],true)){flash('error','Complete all required room fields with valid values.');rooms_redirect();}
  $conn->begin_transaction(); try {
    $q=$conn->prepare('SELECT id FROM rooms WHERE room_number=? AND id<>?');$q->bind_param('si',$number,$id);$q->execute();if($q->get_result()->num_rows)throw new Exception('That room number already exists.');
    if($action==='add'){ $available=$beds;$effective=$status==='Maintenance'?'Maintenance':'Available';$q=$conn->prepare('INSERT INTO rooms (room_number,room_type,location,hostel_block,floor,fees_per_sem,total_beds,available_beds,room_status) VALUES (?,?,?,?,?,?,?,?,?)');$q->bind_param('sssssdiis',$number,$type,$location,$block,$floor,$fees,$beds,$available,$effective);$q->execute();$id=$conn->insert_id; }
    elseif($action==='edit'){ $q=$conn->prepare("SELECT COUNT(*) reserved FROM room_requests WHERE room_id=? AND status IN ('Pending','Approved') FOR UPDATE");$q->bind_param('i',$id);$q->execute();$reserved=(int)$q->get_result()->fetch_assoc()['reserved'];if($beds<$reserved)throw new Exception("Total beds cannot be lower than the $reserved active reservation(s).");$available=$beds-$reserved;$effective=$status==='Maintenance'?'Maintenance':($available===0?'Full':'Available');$q=$conn->prepare('UPDATE rooms SET room_number=?,room_type=?,location=?,hostel_block=?,floor=?,fees_per_sem=?,total_beds=?,available_beds=?,room_status=? WHERE id=?');$q->bind_param('sssssdiisi',$number,$type,$location,$block,$floor,$fees,$beds,$available,$effective,$id);$q->execute(); }
    else throw new Exception('Invalid room action.');
    save_room_images($conn,$id); $conn->commit();flash('success',$action==='add'?'Room added successfully.':'Room details and images updated.');
  }catch(Throwable $e){$conn->rollback();flash('error',$e->getMessage());}rooms_redirect();
}

$edit=null;$editImages=[];if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$q=$conn->prepare('SELECT * FROM rooms WHERE id=?');$q->bind_param('i',$id);$q->execute();$edit=$q->get_result()->fetch_assoc();if($edit){$q=$conn->prepare('SELECT * FROM room_images WHERE room_id=? ORDER BY sort_order');$q->bind_param('i',$id);$q->execute();$editImages=$q->get_result()->fetch_all(MYSQLI_ASSOC);}}
$view=null;$viewImages=[];if(isset($_GET['view'])){$id=(int)$_GET['view'];$q=$conn->prepare('SELECT * FROM rooms WHERE id=?');$q->bind_param('i',$id);$q->execute();$view=$q->get_result()->fetch_assoc();if($view){$q=$conn->prepare('SELECT * FROM room_images WHERE room_id=? ORDER BY sort_order');$q->bind_param('i',$id);$q->execute();$viewImages=$q->get_result()->fetch_all(MYSQLI_ASSOC);if(!$viewImages&&$view['image_path'])$viewImages=[['image_path'=>room_image($view)]];}}
$search=trim($_GET['q']??'');$typeFilter=trim($_GET['type']??'');$page=max(1,(int)($_GET['page']??1));$per=10;$where=' WHERE 1=1';$params=[];$types='';if($search!==''){$where.=' AND (r.room_number LIKE ? OR r.room_type LIKE ? OR r.hostel_block LIKE ?)';$like="%$search%";$params=[$like,$like,$like];$types='sss';}if($typeFilter!==''){$where.=' AND r.room_type=?';$params[]=$typeFilter;$types.='s';}$count=$conn->prepare("SELECT COUNT(*) c FROM rooms r $where");if($params)$count->bind_param($types,...$params);$count->execute();$total=(int)$count->get_result()->fetch_assoc()['c'];$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;$sql="SELECT r.*,(r.total_beds-r.available_beds) occupied_beds,(SELECT image_path FROM room_images WHERE room_id=r.id ORDER BY sort_order LIMIT 1) primary_image,(SELECT COUNT(*) FROM room_images WHERE room_id=r.id) image_count FROM rooms r $where ORDER BY r.room_number LIMIT ? OFFSET ?";$stmt=$conn->prepare($sql);$args=$params;$args[]=$per;$args[]=$offset;$stmt->bind_param($types.'ii',...$args);$stmt->execute();$rooms=$stmt->get_result();$roomTypes=$conn->query('SELECT DISTINCT room_type FROM rooms ORDER BY room_type');$flash=consume_flash();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Room Management | StaySpace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/app.css"><link rel="stylesheet" href="assets/css/room-images.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script></head><body><div class="app"><aside class="sidebar"><div class="brand"><i class="fa-solid fa-building-shield"></i><span>StaySpace</span></div><div class="nav-label">ADMIN CONTROL</div><nav class="nav"><a href="admin_dashboard.php"><i class="fa-solid fa-chart-pie"></i><span>Dashboard</span></a><a class="active" href="admin_rooms.php"><i class="fa-solid fa-bed"></i><span>Room management</span></a><a href="admin_students.php"><i class="fa-solid fa-users"></i><span>Student management</span></a><a class="logout" href="logout.php"><i class="fa-solid fa-arrow-right-from-bracket"></i><span>Sign out</span></a></nav></aside><main class="content"><header class="topbar"><div><h1>Room management</h1><p class="eyebrow">Add, maintain and monitor hostel capacity.</p></div><a class="btn btn-light" href="admin_dashboard.php">Dashboard</a></header>
<?php if($view):?><section class="card"><div class="card-heading"><h2>Room <?=e($view['room_number'])?> image gallery</h2><a class="btn btn-light" href="admin_rooms.php">Close</a></div><?php if($viewImages):?><div class="image-gallery"><?php foreach($viewImages as $i=>$image):?><button class="gallery-item" type="button" data-gallery='<?=e(json_encode(array_column($viewImages,'image_path')))?>' data-index="<?=$i?>"><img src="<?=e($image['image_path'])?>" alt="Room image"></button><?php endforeach;?></div><?php else:?><p class="muted">No room images uploaded.</p><?php endif;?></section><?php endif;?>
<section class="card"><div class="card-heading"><h2><?=$edit?'Edit room':'Add a room'?></h2><?php if($edit):?><a class="btn btn-light" href="admin_rooms.php">Cancel edit</a><?php endif;?></div><form method="post" enctype="multipart/form-data" id="room-form"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="form-grid"><div class="form-group"><label>Room number *</label><input name="room_number" required value="<?=e($edit['room_number']??'')?>"></div><div class="form-group"><label>Room type *</label><input name="room_type" required value="<?=e($edit['room_type']??'')?>"></div><div class="form-group"><label>Hostel block *</label><input name="hostel_block" required value="<?=e($edit['hostel_block']??'')?>"></div><div class="form-group"><label>Floor *</label><input name="floor" required value="<?=e($edit['floor']??'')?>"></div><div class="form-group"><label>Total beds *</label><input type="number" min="1" name="total_beds" required value="<?=e($edit['total_beds']??'')?>"></div><div class="form-group"><label>Fees per semester *</label><input type="number" min="0" step="0.01" name="fees_per_sem" required value="<?=e($edit['fees_per_sem']??'')?>"></div><div class="form-group"><label>Room status *</label><select name="room_status"><option value="Available" <?=($edit['room_status']??'')!=='Maintenance'?'selected':''?>>Available</option><option value="Maintenance" <?=($edit['room_status']??'')==='Maintenance'?'selected':''?>>Maintenance</option></select></div><div class="form-group"><label>Location note</label><input name="location" value="<?=e($edit['location']??'')?>"></div></div><?php if($editImages):?><div class="existing-images"><strong>Existing images</strong><div class="image-gallery compact"><?php foreach($editImages as $image):?><label class="gallery-item"><img src="<?=e($image['image_path'])?>" alt="Room image"><span><input type="checkbox" name="delete_image[]" value="<?=$image['id']?>"> Delete</span></label><?php endforeach;?></div></div><?php endif;?><div class="drop-zone" data-upload-zone><i class="fa-solid fa-cloud-arrow-up"></i><strong>Drag & Drop images here or Click to Browse (Maximum 3 Images)</strong><small data-image-count><?=count($editImages)?> of 3 images selected</small><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple data-image-input></div><div class="image-previews" data-image-previews></div><button class="btn btn-primary" style="margin-top:18px"><i class="fa-solid fa-floppy-disk"></i> <?=$edit?'Save changes':'Add room'?></button></form></section>
<section class="card"><div class="card-heading"><h2>All rooms</h2><span class="muted"><?=$total?> rooms</span></div><form class="toolbar" method="get"><input class="field" name="q" value="<?=e($search)?>" placeholder="Search room, type or block"><select name="type"><option value="">All types</option><?php while($t=$roomTypes->fetch_assoc()):?><option value="<?=e($t['room_type'])?>" <?=$typeFilter===$t['room_type']?'selected':''?>><?=e($t['room_type'])?></option><?php endwhile;?></select><button class="btn btn-primary">Search</button></form><div class="table-wrap"><table><thead><tr><th>Room</th><th>Block / floor</th><th>Capacity</th><th>Occupied</th><th>Available</th><th>Status</th><th>Fee</th><th>Actions</th></tr></thead><tbody><?php if(!$rooms->num_rows):?><tr><td colspan="8" class="empty">No rooms match your search.</td></tr><?php else:while($r=$rooms->fetch_assoc()):$thumbnail=$r['primary_image']?:room_image($r);?><tr><td><span class="room-thumb"><img src="<?=e($thumbnail)?>" alt="Room"><span class="room-thumb-text"><strong><?=e($r['room_number'])?></strong><br><small class="muted"><?=e($r['room_type'])?></small></span><?php if($r['image_count']>1):?><b>+<?=($r['image_count']-1)?></b><?php endif;?></span></td><td><?=e($r['hostel_block']?:'—')?> / <?=e($r['floor']?:$r['location'])?></td><td><?=$r['total_beds']?></td><td><?=$r['occupied_beds']?></td><td><?=$r['available_beds']?></td><td><span class="badge <?=strtolower($r['room_status'])==='available'?'available':'full'?>"><?=e($r['room_status'])?></span></td><td>₹<?=number_format($r['fees_per_sem'])?></td><td><a class="btn btn-light" href="?view=<?=$r['id']?>">View</a> <a class="btn btn-light" href="?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger" data-confirm="Delete this room and its related requests?">Delete</button></form></td></tr><?php endwhile;endif;?></tbody></table></div></section></main></div><div class="lightbox" data-lightbox hidden><button class="lightbox-close" type="button">×</button><button class="lightbox-prev" type="button">‹</button><img src="" alt="Room image"><button class="lightbox-next" type="button">›</button></div><?php if($flash):?><div id="flash" data-type="<?=e($flash['type'])?>" data-message="<?=e($flash['text'])?>"></div><?php endif;?><script src="assets/js/app.js"></script><script src="assets/js/room-images.js"></script><script>const f=document.getElementById('flash');if(f)Swal.fire({toast:true,position:'top-end',showConfirmButton:false,timer:3500,icon:f.dataset.type==='success'?'success':'error',title:f.dataset.message});</script></body></html>
